#include <stdio.h>

int main(void) {
    int n, v[500];
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%d", &v[i]);
    }

    int answer = 1;

    for (int a = 1; a <= n; a++) {
        for (int b = a + 1; b <= n; b++) {
            int last = 0;
            int runs = 0;

            for (int i = 0; i < n; i++) {
                if (v[i] == a || v[i] == b) {
                    if (v[i] != last) {
                        runs++;
                        last = v[i];
                    }
                }
            }

            if (runs > answer) answer = runs;
        }
    }

    printf("%d\n", answer);
    return 0;
}
